INSERT INTO Drinker (name, address) VALUES ('Alice', 'Addr1');
INSERT INTO Drinker (name, address) VALUES ('Bob', 'Addr2');

INSERT INTO Bar (name, address) VALUES ('Bar1', 'BarAddress1');

INSERT INTO Beer (name, brewer) VALUES ('Beer1', 'Brewer1');

-- Alice does not frequent any bar, Bob frequents Bar1
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bob', 'Bar1', 3);

