INSERT INTO Serves (bar, beer, price) VALUES ('Bar1', 'Beer1', 5.00);

-- Bob does not like Beer1 (i.e. no INSERT for Bob liking Beer1), so leave Likes table empty or insert other likes if needed
-- Optionally, insert a like for Alice so she is not trivially satisfied by having no data in Likes
INSERT INTO Likes (drinker, beer) VALUES ('Alice', 'Beer1');

