-- Insert bars
INSERT INTO Bar (name, address) VALUES ('Bar1', 'Address1');
INSERT INTO Bar (name, address) VALUES ('Bar2', 'Address2');

-- Insert beer
INSERT INTO Beer (name, brewer) VALUES ('BeerX', 'Brewer1');

-- Insert drinker
INSERT INTO Drinker (name, address) VALUES ('Bob', 'SomeAddress');

-- Insert frequents: Bob frequents both bars
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bob', 'Bar1', 3);
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Bob', 'Bar2', 2);

-- Insert serves: BeerX is served at both bars with different prices
INSERT INTO Serves (bar, beer, price) VALUES ('Bar1', 'BeerX', 5.00);
INSERT INTO Serves (bar, beer, price) VALUES ('Bar2', 'BeerX', 7.00);

-- Note: No Likes record is inserted for Bob and BeerX, so Q2's join on Likes will fail to include BeerX.

